use std::env;
use std::fs;
use std::path::{Path, PathBuf};
use std::os::unix::fs::MetadataExt;
use std::os::unix::fs::PermissionsExt;
use std::time::SystemTime;

struct Options {
    paths: Vec<PathBuf>,
    details: Vec<String>,
    importance: i32,
    sort: Vec<String>,
    show_icons: bool,
    show_suffix: bool,
    show_symlink_targets: bool,
    align_dotfiles: bool,
    units: String,
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let mut options = Options {
        paths: Vec::new(),
        details: Vec::new(),
        importance: 0,
        sort: vec!["cat".to_string(), "cname".to_string()],
        show_icons: true,
        show_suffix: true,
        show_symlink_targets: true,
        align_dotfiles: true,
        units: "binary".to_string(),
    };

    let mut i = 1;
    while i < args.len() {
        match args[i].as_str() {
            "-h" | "--help" => {
                print_help();
                return;
            }
            "-V" | "--version" => {
                println!("pls 0.0.1-beta.9");
                return;
            }
            "-d" | "--det" => {
                i += 1;
                if i < args.len() {
                    options.details.push(args[i].clone());
                }
            }
            "-I" | "--imp" => {
                i += 1;
                if i < args.len() {
                    options.importance = args[i].parse().unwrap_or(0);
                }
            }
            "-s" | "--sort" => {
                i += 1;
                if i < args.len() {
                    options.sort = args[i].split_whitespace().map(|s| s.to_string()).collect();
                }
            }
            "-u" | "--unit" => {
                i += 1;
                if i < args.len() {
                    options.units = args[i].clone();
                }
            }
            "-i" | "--icon" => {
                i += 1;
                if i < args.len() {
                    options.show_icons = args[i] == "true";
                }
            }
            "-S" | "--suffix" => {
                i += 1;
                if i < args.len() {
                    options.show_suffix = args[i] == "true";
                }
            }
            "-l" | "--sym" => {
                i += 1;
                if i < args.len() {
                    options.show_symlink_targets = args[i] == "true";
                }
            }
            "-a" | "--align" => {
                i += 1;
                if i < args.len() {
                    options.align_dotfiles = args[i] == "true";
                }
            }
            arg if arg.starts_with("--imp=") => {
                options.importance = arg["--imp=".len()..].parse().unwrap_or(0);
            }
            arg if arg.starts_with("-") => {
                // Ignore other options for now
            }
            path => {
                options.paths.push(PathBuf::from(path));
            }
        }
        i += 1;
    }

    if options.paths.is_empty() {
        options.paths.push(PathBuf::from("."));
    }

    if options.details.is_empty() {
        options.details.push("none".to_string());
    }

    for path in &options.paths {
        list_path(path, &options);
    }
}

fn print_help() {
    // Implement help later
}

fn list_path(path: &Path, options: &Options) {
    let entries = match fs::read_dir(path) {
        Ok(e) => e,
        Err(e) => {
            eprintln!("{}: {}", path.display(), e);
            return;
        }
    };

    let mut nodes = Vec::new();
    for entry in entries {
        if let Ok(entry) = entry {
            let name = entry.file_name().into_string().unwrap_or_default();
            if name.starts_with('.') && options.importance >= 0 {
                continue;
            }
            nodes.push(entry);
        }
    }

    // Sort nodes based on options.sort
    // Cat: Directory < everything else
    nodes.sort_by(|a, b| {
        let meta_a = a.metadata().unwrap();
        let meta_b = b.metadata().unwrap();
        let cat_a = if meta_a.is_dir() { 0 } else { 1 };
        let cat_b = if meta_b.is_dir() { 0 } else { 1 };

        if cat_a != cat_b {
            return cat_a.cmp(&cat_b);
        }

        let name_a = a.file_name().into_string().unwrap().to_lowercase();
        let name_b = b.file_name().into_string().unwrap().to_lowercase();
        name_a.cmp(&name_b)
    });

    for node in nodes {
        let name = node.file_name().into_string().unwrap();
        println!("{}", name);
    }
}
EOF
cargo build"}

