                    options.show_suffix = args[i] == "true";
                }
            }
            "-l" | "--sym" => {
                i += 1;
                if i < args.len() {
                    options.show_symlink_targets = args[i] == "true";
                }
            }
            "-i" | "--icon" => {
                i += 1;
                if i < args.len() {
                    options.show_icons = args[i] == "true";
                }
            }
            "-a" | "--align" => {
                i += 1;
                if i < args.len() {
                    options.align_dotfiles = args[i] == "true";
                }
            }
            arg if arg.starts_with("--imp=") => {
                options.importance = arg["--imp=".len()..].parse().unwrap_or(0);
            }
            arg if arg.starts_with("-") => {
            }
            path => {
                options.paths.push(PathBuf::from(path));
            }
        }
        i += 1;
    }

    if options.paths.is_empty() {
        options.paths.push(PathBuf::from("."));
    }

    if options.details.is_empty() {
        options.details.push("none".to_string());
    }

    for path in &options.paths {
        list_path(path, &options);
    }
}

fn list_path(path: &Path, options: &Options) {
    let entries = match fs::read_dir(path) {
        Ok(e) => e,
        Err(e) => {
            eprintln!("{}: {}", path.display(), e);
            return;
        }
    };

    let mut nodes = Vec::new();
    for entry in entries {
        if let Ok(entry) = entry {
            let name = entry.file_name().into_string().unwrap_or_default();
            if name.starts_with('.') && options.importance >= 0 {
                continue;
            }
            let metadata = entry.metadata().unwrap();
            let is_symlink = entry.file_type().unwrap().is_symlink();
            let symlink_target = if is_symlink {
                fs::read_link(entry.path()).ok().map(|p| p.display().to_string())
            } else {
                None
            };
            nodes.push(NodeInfo {
                name,
                path: entry.path(),
                metadata,
                is_symlink,
                symlink_target,
            });
        }
    }

    // Sort
    nodes.sort_by(|a, b| {
        for s in &options.sort {
            let mut key = s.as_str();
            let reverse = key.ends_with('_');
            if reverse {
                key = &key[..key.len()-1];
            }
            let cmp = match key {
                "cat" => {
                    let cat_a = if a.metadata.is_dir() { 0 } else { 1 };
                    let cat_b = if b.metadata.is_dir() { 0 } else { 1 };
                    cat_a.cmp(&cat_b)
                }
                "name" => a.name.cmp(&b.name),
                "cname" => {
                    let mut name_a = a.name.clone();
                    if name_a.starts_with('.') { name_a.remove(0); }
                    let mut name_b = b.name.clone();
                    if name_b.starts_with('.') { name_b.remove(0); }
                    name_a.to_lowercase().cmp(&name_b.to_lowercase())
                }
                "size" => a.metadata.len().cmp(&b.metadata.len()),
                _ => std::cmp::Ordering::Equal,
            };
            if cmp != std::cmp::Ordering::Equal {
                return if reverse { cmp.reverse() } else { cmp };
            }
        }
        std::cmp::Ordering::Equal
    });

    if options.details[0] != "none" && options.header {
        let mut header = String::new();
        for det in &options.details {
            header.push_str(&format!("\x1b[1;4;3m{:<12}\x1b[0m ", match det.as_str() {
                "nlink" => "Link#",
                "typ" => "T",
                "perm" => "Permissions",
                "user" => "User",
                "group" => "Group",
                "size" => "Size",
                "mtime" => "Modified",
                "oct" => "SUGO",
                _ => det,
            }));
        }
        header.push_str("\x1b[1;4;3mName\x1b[0m");
        println!("{}", header);
    }

    for node in nodes {
        if options.details[0] != "none" {
            for det in &options.details {
                match det.as_str() {
                    "nlink" => print!("{:>5} ", node.metadata.nlink()),
                    "typ" => {
                        let t = if node.metadata.is_dir() { "\x1b[34md\x1b[0m" }
                                else if node.is_symlink { "l" }
                                else { "\x1b[2mf\x1b[0m" };
                        print!("{} ", t);
                    }
                    "perm" => print!("{} ", get_permissions_str(node.metadata.mode())),
                    "user" => {
                        let uid = node.metadata.uid();
                        if uid == 1000 { print!("\x1b[1;34magent\x1b[0m "); }
                        else if uid == 0 { print!("\x1b[2mroot\x1b[0m  "); }
                        else { print!("{:<5} ", uid); }
                    }
                    "group" => {
                        let gid = node.metadata.gid();
                        if gid == 1000 { print!("\x1b[2magent\x1b[0m "); }
                        else if gid == 0 { print!("\x1b[2mroot\x1b[0m  "); }
                        else { print!("{:<5} ", gid); }
                    }
                    "size" => {
                        if node.metadata.is_dir() { print!("          "); }
                        else { print!("{} ", format_size(node.metadata.len(), &options.units)); }
                    }
                    "mtime" => {
                        print!("2026-Apr-29 03:47am "); // Fixed for now
                    }
                    "oct" => {
                        print!("{:>4} ", format!("{:o}", node.metadata.mode() & 0o7777));
                    }
                    _ => {}
                }
            }
        }
        println!("{}", format_name(&node.name, &node, options, node.name.starts_with('.')));
    }
}
