    details: Vec<String>,
    importance: i32,
    sort: Vec<String>,
    show_icons: bool,
    show_suffix: bool,
    show_symlink_targets: bool,
    align_dotfiles: bool,
    units: String,
    header: bool,
}

struct NodeInfo {
    name: String,
    path: PathBuf,
    metadata: fs::Metadata,
    is_symlink: bool,
    symlink_target: Option<String>,
}

fn get_icon(name: &str, is_dir: bool, is_link: bool, is_pipe: bool, is_socket: bool) -> (&'static str, &'static str) {
    if is_dir {
        if name == ".git" {
            return ("\u{f2a2}", "34"); // nf-fa-git, blue
        }
        return ("\u{f07b}", "34"); // nf-fa-folder, blue
    }
    if is_link {
        return ("\u{f339}", "35"); // nf-oct-link, magenta (wait, I saw magenta arrow, let's check symlink icon color)
        // Actually I'll check the color again.
    }
    if is_pipe {
        return ("\u{f07e5}", "33"); // nf-md-pipe, yellow? (I'll check)
    }
    if is_socket {
        return ("\u{f07e8}", "32"); // nf-md-socket, green?
    }

    let lower_name = name.to_lowercase();
    if lower_name == "license" {
        return ("\u{f495}", ""); // nf-md-license
    }
    if lower_name == "readme.md" {
        return ("\u{f02d}", ""); // nf-fa-book
    }
    if lower_name == "makefile" {
        return ("\u{f070e}", ""); // nf-md-makefile
    }
    if lower_name == "cargo.toml" {
        return ("\u{f487}", ""); // nf-md-package
    }
    if lower_name == "dockerfile" {
        return ("\u{f4b7}", ""); // nf-md-docker
    }
    if lower_name == ".gitignore" {
        return ("\u{f2a2}", ""); // same as .git
    }

    if let Some(ext) = Path::new(name).extension().and_then(|s| s.to_str()) {
        match ext.to_lowercase().as_str() {
            "rs" => return ("\u{e68b}", "91"), // nf-custom-rust, bright red
            "md" => return ("\u{f48a}", ""), // nf-md-markdown
            "json" | "yaml" | "toml" => return ("\u{e60b}", ""), // nf-custom-cpp_stylable? No, nf-set-json
            "sh" => return ("\u{f489}", ""), // nf-md-bash
            "txt" => return ("\u{e612}", ""), // nf-custom-text
            "mkv" | "mp4" => return ("\u{f0567}", ""),
            "png" | "jpg" | "jpeg" | "gif" | "svg" => return ("\u{f02e9}", ""),
            "mp3" | "wav" => return ("\u{f04c3}", ""),
            _ => {}
        }
    }
    ("", "")
}

fn format_name(name: &str, info: &NodeInfo, options: &Options, dim: bool) -> String {
    let is_dir = info.metadata.is_dir();
    let is_link = info.is_symlink;
    let is_pipe = info.metadata.file_type().is_fifo();
    let is_socket = info.metadata.file_type().is_socket();
    let (icon, icon_color) = if options.show_icons {
        get_icon(name, is_dir, is_link, is_pipe, is_socket)
    } else {
        ("", "")
    };

    let mut result = String::new();

    // Icon and Alignment
    if options.show_icons {
        if icon.is_empty() {
            result.push_str("   ");
        } else {
            if !icon_color.is_empty() {
                result.push_str(&format!("\x1b[{}m{}\x1b[0m ", icon_color, icon));
            } else {
                result.push_str(&format!("{} ", icon));
            }
            if name.starts_with('.') && options.align_dotfiles {
                result.push_str(""); // Already handled by the space after icon
            } else {
                result.push_str(" ");
            }
        }
    }

    if name.starts_with('.') && options.align_dotfiles {
        if !options.show_icons {
            result.push_str("  ");
        }
        result.push_str("\x1b[2m.\x1b[0m");
        let rest = &name[1..];
        if is_dir {
            result.push_str(&format!("\x1b[34m{}\x1b[0m", rest));
        } else if name.to_lowercase() == ".gitignore" {
             result.push_str(rest);
        } else if dim {
            result.push_str(&format!("\x1b[2m{}\x1b[0m", rest));
        } else {
            result.push_str(rest);
        }
    } else {
        if !options.show_icons {
            result.push_str("   ");
        }
        let style = if is_dir {
            "\x1b[34m"
        } else if name == "LICENSE" || name == "executable" {
            "\x1b[3m"
        } else if name == "README.md" {
            "\x1b[4m"
        } else if name.ends_with(".rs") {
            "\x1b[91m"
        } else if dim {
            "\x1b[2m"
        } else {
            ""
        };
        if !style.is_empty() {
            result.push_str(&format!("{}{}\x1b[0m", style, name));
        } else {
            result.push_str(name);
        }
    }

    if options.show_suffix {
        if is_dir {
            result.push_str("\x1b[2;34m/\x1b[0m");
        } else if is_link {
            result.push_str("\x1b[2m@\x1b[0m");
        } else if is_pipe {
            result.push_str("\x1b[2m|\x1b[0m");
        } else if is_socket {
            result.push_str("\x1b[2m=\x1b[0m");
        }
    }

    if options.show_symlink_targets && is_link {
        if let Some(target) = &info.symlink_target {
            result.push_str(&format!(" \x1b[35m\u{f0054}\x1b[0m {}", target));
        }
    }

    result
}

fn format_size(size: u64, units: &str) -> String {
    if units == "none" {
        return "".to_string();
    }
    let (base, suffix) = if units == "binary" {
        (1024.0, vec!["B", "KiB", "MiB", "GiB", "TiB"])
    } else {
        (1000.0, vec!["B", "KB", "MB", "GB", "TB"])
    };

    if size < base as u64 {
        return format!("{:>5.1}   \x1b[2m{}\x1b[0m", size as f64, suffix[0]);
    }

    let mut s = size as f64;
    let mut i = 0;
    while s >= base && i < suffix.len() - 1 {
        s /= base;
        i += 1;
    }

    format!("{:>5.1} \x1b[2m{}\x1b[0m", s, suffix[i])
}

fn get_permissions_str(mode: u32) -> String {
    let r = "\x1b[33mr\x1b[0m";
    let w = "\x1b[31mw\x1b[0m";
    let x = "\x1b[32mx\x1b[0m";
    let dash = "\x1b[2m-\x1b[0m";

    let mut s = String::new();
    for i in (0..3).rev() {
        let bits = (mode >> (i * 3)) & 0x7;
        s.push_str(if bits & 4 != 0 { r } else { dash });
        s.push_str(if bits & 2 != 0 { w } else { dash });
        s.push_str(if bits & 1 != 0 { x } else { dash });
        if i > 0 { s.push_str(" "); }
    }
    s
}

