    tm_yday: i32,
    tm_isdst: i32,
    tm_gmtoff: i64,
    tm_zone: *const i8,
}

fn format_time(seconds: i64) -> String {
    let mut tm = Tm {
        tm_sec: 0, tm_min: 0, tm_hour: 0, tm_mday: 0, tm_mon: 0, tm_year: 0,
        tm_wday: 0, tm_yday: 0, tm_isdst: 0, tm_gmtoff: 0, tm_zone: std::ptr::null(),
    };
    unsafe {
        localtime_r(&seconds, &mut tm);
    }
    let months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
    let hour = if tm.tm_hour % 12 == 0 { 12 } else { tm.tm_hour % 12 };
    let am_pm = if tm.tm_hour < 12 { "am" } else { "pm" };
    format!(
        "{:04}-{}-{:02} {:02}:{:02}{}",
        tm.tm_year + 1900,
        months[tm.tm_mon as usize],
        tm.tm_mday,
        hour,
        tm.tm_min,
        am_pm
    )
}

struct Options {
    paths: Vec<PathBuf>,
    details: Vec<String>,
    importance: i32,
    sort: Vec<String>,
    show_icons: bool,
    show_suffix: bool,
