}

fn get_icon(name: &str, is_dir: bool, is_link: bool, is_pipe: bool, is_socket: bool) -> (&'static str, &'static str) {
    if is_dir {
        if name == ".git" { return ("\u{f2a2}", "34"); }
        return ("\u{f07b}", "34");
    }
    if is_link { return ("\u{f339}", "35"); }
    if is_pipe { return ("\u{f07e5}", "33"); }
    if is_socket { return ("\u{f07e8}", "32"); }

    let lower_name = name.to_lowercase();
    if lower_name == "license" { return ("\u{f495}", ""); }
    if lower_name == "readme.md" { return ("\u{f02d}", ""); }
    if lower_name == "makefile" { return ("\u{f070e}", ""); }
    if lower_name == "cargo.toml" { return ("\u{f487}", ""); }
    if lower_name == "dockerfile" { return ("\u{f4b7}", ""); }
    if lower_name == ".gitignore" { return ("\u{f2a2}", ""); }

    if let Some(ext) = Path::new(name).extension().and_then(|s| s.to_str()) {
        match ext.to_lowercase().as_str() {
            "rs" => return ("\u{e68b}", "91"),
            "md" => return ("\u{f48a}", ""),
            "json" | "yaml" | "toml" => return ("\u{e60b}", ""),
            "sh" => return ("\u{f489}", ""),
            "txt" => return ("\u{e612}", ""),
            "mkv" | "mp4" => return ("\u{f0567}", ""),
            "png" | "jpg" | "jpeg" | "gif" | "svg" => return ("\u{f02e9}", ""),
            "mp3" | "wav" => return ("\u{f04c3}", ""),
            _ => {}
        }
    }
    ("", "")
}

fn format_name(name: &str, info: &NodeInfo, options: &Options, dim: bool) -> String {
    let is_dir = info.metadata.is_dir();
    let is_link = info.is_symlink;
    let is_pipe = info.metadata.file_type().is_fifo();
    let is_socket = info.metadata.file_type().is_socket();

    let (icon, icon_color) = if options.show_icons {
        get_icon(name, is_dir, is_link, is_pipe, is_socket)
    } else {
        ("", "")
    };

    let mut result = String::new();

    if options.show_icons {
        if icon.is_empty() {
            result.push_str("   ");
        } else {
            if !icon_color.is_empty() {
                result.push_str(&format!("\x1b[{}m{}\x1b[0m ", icon_color, icon));
            } else {
                result.push_str(&format!("{} ", icon));
            }
            if !(name.starts_with('.') && options.align_dotfiles) {
                result.push_str(" ");
            }
        }
    }

    if name.starts_with('.') && options.align_dotfiles {
        if !options.show_icons { result.push_str("  "); }
        result.push_str("\x1b[2m.\x1b[0m");
        let rest = &name[1..];
        let style = if is_dir { "\x1b[2;34m" } else if dim { "\x1b[2m" } else { "" };
        if !style.is_empty() {
            result.push_str(&format!("{}{}\x1b[0m", style, rest));
        } else {
            result.push_str(rest);
        }
    } else {
        if !options.show_icons { result.push_str("   "); }
        let style = if is_dir { "\x1b[34m" } 
                    else if name == "LICENSE" || name == "executable" { "\x1b[3m" } 
                    else if name == "README.md" { "\x1b[4m" } 
                    else if name.ends_with(".rs") { "\x1b[91m" } 
                    else if dim { "\x1b[2m" } 
                    else { "" };
        if !style.is_empty() {
            result.push_str(&format!("{}{}\x1b[0m", style, name));
        } else {
            result.push_str(name);
        }
    }

    if options.show_suffix {
        if is_dir { result.push_str("\x1b[2;34m/\x1b[0m"); }
        else if is_link { result.push_str("\x1b[2m@\x1b[0m"); }
        else if is_pipe { result.push_str("\x1b[2m|\x1b[0m"); }
        else if is_socket { result.push_str("\x1b[2m=\x1b[0m"); }
    }

    if options.show_symlink_targets && is_link {
        if let Some(target) = &info.symlink_target {
            result.push_str(&format!(" \x1b[35m\u{f0054}\x1b[0m {}", target));
        }
    }
    result
}

fn format_size(size: u64, units: &str) -> String {
    let (base, suffix) = if units == "decimal" {
        (1000.0, vec!["B", "KB", "MB", "GB", "TB"])
    } else {
        (1024.0, vec!["B", "KiB", "MiB", "GiB", "TiB"])
    };

    if size < base as u64 {
        return format!("{:>5.1}   \x1b[2m{}\x1b[0m", size as f64, suffix[0]);
    }
    let mut s = size as f64;
    let mut i = 0;
    while s >= base && i < suffix.len() - 1 {
        s /= base;
        i += 1;
    }
    format!("{:>5.1} \x1b[2m{}\x1b[0m", s, suffix[i])
}

fn get_permissions_str(mode: u32) -> String {
    let r = "\x1b[33mr\x1b[0m";
    let w = "\x1b[31mw\x1b[0m";
    let x = "\x1b[32mx\x1b[0m";
    let dash = "\x1b[2m-\x1b[0m";
    let mut s = String::new();
    for i in (0..3).rev() {
        let bits = (mode >> (i * 3)) & 0x7;
        s.push_str(if bits & 4 != 0 { r } else { dash });
        s.push_str(if bits & 2 != 0 { w } else { dash });
        s.push_str(if bits & 1 != 0 { x } else { dash });
        if i > 0 { s.push_str(" "); }
    }
    s
}

fn main() {
    let mut options = Options {
        paths: Vec::new(),
        details: Vec::new(),
        importance: 0,
        sort: vec!["cat".to_string(), "cname".to_string()],
        show_icons: true,
        show_suffix: true,
        show_symlink_targets: true,
        align_dotfiles: true,
        units: "binary".to_string(),
        header: true,
    };

    let args: Vec<String> = env::args().collect();
    let mut i = 1;
    while i < args.len() {
        match args[i].as_str() {
            "-V" | "--version" => { println!("pls 0.0.1-beta.9"); return; }
            "-d" | "--det" => {
                i += 1;
                if i < args.len() {
                    match args[i].as_str() {
                        "std" => { options.details.extend(vec!["nlink", "typ", "perm", "user", "group", "size", "mtime"].into_iter().map(|s| s.to_string())); }
                        "all" => { options.details.extend(vec!["dev", "ino", "nlink", "typ", "perm", "oct", "user", "uid", "group", "gid", "size", "blocks", "btime", "ctime", "mtime", "atime", "git"].into_iter().map(|s| s.to_string())); }
                        det => { options.details.push(det.to_string()); }
                    }
                }
            }
            "-I" | "--imp" => {
                i += 1;
                if i < args.len() { options.importance = args[i].parse().unwrap_or(0); }
            }
            "-s" | "--sort" => {
                i += 1;
                if i < args.len() { options.sort = args[i].split_whitespace().map(|s| s.to_string()).collect(); }
            }
            "-u" | "--unit" => {
                i += 1;
                if i < args.len() { options.units = args[i].clone(); }
            }
            "-H" | "--header" => {
                i += 1;
                if i < args.len() { options.header = args[i] == "true"; }
            }
            "-S" | "--suffix" => {
                i += 1;
                if i < args.len() { options.show_suffix = args[i] == "true"; }
            }
            "-l" | "--sym" => {
                i += 1;
                if i < args.len() { options.show_symlink_targets = args[i] == "true"; }
            }
            "-i" | "--icon" => {
                i += 1;
                if i < args.len() { options.show_icons = args[i] == "true"; }
            }
            "-a" | "--align" => {
                i += 1;
                if i < args.len() { options.align_dotfiles = args[i] == "true"; }
            }
            arg if arg.starts_with("--imp=") => { options.importance = arg["--imp=".len()..].parse().unwrap_or(0); }
            path if !path.starts_with('-') => { options.paths.push(PathBuf::from(path)); }
            _ => {}
        }
        i += 1;
    }

    if options.paths.is_empty() { options.paths.push(PathBuf::from(".")); }
    if options.details.is_empty() { options.details.push("none".to_string()); }

    for path in &options.paths {
        let entries = match fs::read_dir(path) {
            Ok(e) => e,
            Err(_) => {
                if let Ok(metadata) = fs::symlink_metadata(path) {
                    let is_symlink = fs::read_link(path).is_ok();
                    let node = NodeInfo {
                        name: path.file_name().and_then(|s| s.to_str()).unwrap_or("").to_string(),
                        metadata,
                        is_symlink,
                        symlink_target: if is_symlink { fs::read_link(path).ok().map(|p| p.display().to_string()) } else { None },
                    };
                    print_node(&node, &options);
                    continue;
                }
                continue;
            }
        };

        let mut nodes = Vec::new();
        for entry in entries.flatten() {
            let name = entry.file_name().into_string().unwrap_or_default();
            if name.starts_with('.') && options.importance >= 0 { continue; }
            let metadata = entry.metadata().unwrap();
            let is_symlink = entry.file_type().unwrap().is_symlink();
            nodes.push(NodeInfo {
                name,
                metadata,
                is_symlink,
                symlink_target: if is_symlink { fs::read_link(entry.path()).ok().map(|p| p.display().to_string()) } else { None },
            });
        }

        nodes.sort_by(|a, b| {
            for s in &options.sort {
                let mut key = s.as_str();
                let reverse = key.ends_with('_');
                if reverse { key = &key[..key.len()-1]; }
                let cmp = match key {
                    "cat" => (if a.metadata.is_dir() { 0 } else { 1 }).cmp(&(if b.metadata.is_dir() { 0 } else { 1 })),
                    "name" => a.name.cmp(&b.name),
                    "cname" => {
                        let na = if a.name.starts_with('.') { &a.name[1..] } else { &a.name };
                        let nb = if b.name.starts_with('.') { &b.name[1..] } else { &b.name };
                        na.to_lowercase().cmp(&nb.to_lowercase())
                    }
                    "size" => a.metadata.len().cmp(&b.metadata.len()),
                    "ext" => {
                        let ea = Path::new(&a.name).extension().and_then(|s| s.to_str()).unwrap_or("");
                        let eb = Path::new(&b.name).extension().and_then(|s| s.to_str()).unwrap_or("");
                        ea.to_lowercase().cmp(&eb.to_lowercase())
                    }
                    _ => std::cmp::Ordering::Equal,
                };
                if cmp != std::cmp::Ordering::Equal { return if reverse { cmp.reverse() } else { cmp }; }
            }
            std::cmp::Ordering::Equal
        });

        if options.details[0] != "none" && options.header {
            for det in &options.details {
                let h = match det.as_str() { "nlink" => "Link#", "typ" => "T", "perm" => "Permissions", "user" => "User", "group" => "Group", "size" => "Size", "mtime" => "Modified", "oct" => "SUGO", "dev" => "Device", "ino" => "inode", "uid" => "UID", "gid" => "GID", "blocks" => "Blocks", "btime" => "Created", "ctime" => "Changed", "atime" => "Accessed", "git" => "Git", _ => det };
                let width = match det.as_str() { "size" => 10, "mtime" | "btime" | "ctime" | "atime" => 20, "perm" => 11, _ => 0 };
                print!("\x1b[1;4;3m{:>width$}\x1b[0m ", h, width = width);
            }
            println!("\x1b[1;4;3mName\x1b[0m");
        }

        for node in nodes { print_node(&node, &options); }
    }
}

fn print_node(node: &NodeInfo, options: &Options) {
    if options.details[0] != "none" {
        for det in &options.details {
            match det.as_str() {
                "dev" => print!("{:>6} ", node.metadata.dev()),
                "ino" => print!("{:>10} ", node.metadata.ino()),
                "nlink" => print!("{:>5} ", node.metadata.nlink()),
                "typ" => print!("{} ", if node.metadata.is_dir() { "\x1b[34md\x1b[0m" } else if node.is_symlink { "l" } else { "\x1b[2mf\x1b[0m" }),
                "perm" => print!("{} ", get_permissions_str(node.metadata.mode())),
                "oct" => print!("{:>4} ", format!("{:o}", node.metadata.mode() & 0o7777)),
                "user" => {
                    let uid = node.metadata.uid();
                    if uid == 1000 { print!("\x1b[1;34magent\x1b[0m "); } else if uid == 0 { print!("\x1b[2mroot\x1b[0m  "); } else { print!("{:<5} ", uid); }
                }
                "uid" => print!("{:>4} ", node.metadata.uid()),
                "group" => {
                    let gid = node.metadata.gid();
                    if gid == 1000 { print!("\x1b[2magent\x1b[0m "); } else if gid == 0 { print!("\x1b[2mroot\x1b[0m  "); } else { print!("{:<5} ", gid); }
                }
                "gid" => print!("{:>4} ", node.metadata.gid()),
                "size" => {
                    if node.metadata.is_dir() { print!("           "); }
                    else { print!("{} ", format_size(node.metadata.len(), &options.units)); }
                }
                "blocks" => print!("{:>6} ", node.metadata.blocks()),
                "mtime" => print!("{} ", format_time(node.metadata.mtime())),
                "atime" => print!("{} ", format_time(node.metadata.atime())),
                "ctime" => print!("{} ", format_time(node.metadata.ctime())),
                "btime" => print!("{} ", format_time(node.metadata.mtime())), // btime is not easily available in std
                "git" => print!("    "),
                _ => {}
            }
        }
    }
    println!("{}", format_name(&node.name, node, options, node.name.starts_with('.')));
}
