fn get_icon(name: &str, is_dir: bool, is_link: bool, is_pipe: bool, is_socket: bool) -> (&'static str, &'static str) {
    if is_dir {
        if name == ".git" { return ("\u{f2a2}", "34"); }
        if name == "src" { return ("\u{f40d}", "34"); }
        return ("\u{f07b}", "34");
    }
    if is_link { return ("\u{f339}", "35"); }
    if is_pipe { return ("\u{f07e5}", "33"); }
    if is_socket { return ("\u{f07e8}", "32"); }
    let ln = name.to_lowercase();
    if ln == "license" { return ("\u{f495}", ""); }
    if ln == "readme.md" { return ("\u{f02d}", ""); }
    if ln == "makefile" { return ("\u{f070e}", ""); }
    if ln == "cargo.toml" { return ("\u{f487}", ""); }
    if ln == "cargo.lock" { return ("\u{f456}", ""); }
    if ln == "dockerfile" { return ("\u{f4b7}", ""); }
    if ln == ".gitignore" { return ("\u{f2a2}", ""); }
    if let Some(ext) = Path::new(name).extension().and_then(|s| s.to_str()) {
        match ext.to_lowercase().as_str() {
            "rs" => return ("\u{e68b}", "91"),
            "md" => return ("\u{f48a}", ""),
            "json" | "yaml" | "toml" => return ("\u{e60b}", ""),
            "sh" => return ("\u{f489}", ""),
            "txt" => return ("\u{e612}", ""),
            "mkv" | "mp4" => return ("\u{f0567}", ""),
            "png" | "jpg" | "jpeg" | "gif" | "svg" => return ("\u{f02e9}", ""),
