        else if info.metadata.file_type().is_socket() { res.push_str("\x1b[2m=\x1b[0m"); }
    }
    if options.show_symlink_targets && info.is_symlink {
        if let Some(target) = &info.symlink_target { res.push_str(&format!(" \x1b[35m\u{f0054}\x1b[0m {}", target)); }
    }
    res
}

