                let name = entry.file_name().into_string().unwrap_or_default();
                if name.starts_with('.') && opts.importance >= 0 { continue; }
                let metadata = entry.metadata().unwrap();
                let is_symlink = entry.file_type().unwrap().is_symlink();
                nodes.push(NodeInfo {
                    name, metadata, is_symlink,
                    symlink_target: if is_symlink { fs::read_link(entry.path()).ok().map(|p| p.display().to_string()) } else { None },
                    children: Vec::new(),
                });
            }
        } else if let Ok(metadata) = fs::symlink_metadata(path) {
            let is_symlink = fs::read_link(path).is_ok();
            nodes.push(NodeInfo {
                name: path.file_name().and_then(|s| s.to_str()).unwrap_or("").to_string(),
                metadata, is_symlink,
                symlink_target: if is_symlink { fs::read_link(path).ok().map(|p| p.display().to_string()) } else { None },
