                        let lock = nodes.remove(i);
                        nodes[pos].children.push(lock);
                        continue;
                    }
                }
                i += 1;
            }
        }

        if opts.details[0] != "none" && opts.header && path.is_dir() {
            for det in &opts.details {
                let (h, w) = match det.as_str() { "nlink" => ("Link#", 5), "typ" => ("T", 1), "perm" => ("Permissions", 11), "user" => ("User", 5), "group" => ("Group", 10), "size" => ("Size", 10), "mtime" => ("Modified", 20), "oct" => ("SUGO", 4), _ => (det.as_str(), 0) };
                print!("\x1b[1;4;3m{:>width$}\x1b[0m ", h, width = w);
            }
            println!("\x1b[1;4;3mName\x1b[0m");
        }
        for node in nodes { print_node_recursive(&node, &opts, ""); }
    }
}

fn print_node_recursive(node: &NodeInfo, opts: &Options, indent: &str) {
    if opts.details[0] != "none" {
