    println!("{}", format_name(&node.name, node, opts, node.name.starts_with('.'), indent));
    for child in &node.children { print_node_recursive(child, opts, "   └─ "); }
}

fn format_size(size: u64, units: &str) -> String {
    let (base, suffix) = if units == "decimal" { (1000.0, vec!["B", "KB", "MB", "GB", "TB"]) } else { (1024.0, vec!["B", "KiB", "MiB", "GiB", "TiB"]) };
    if size < base as u64 { return format!("{:>5.1}   \x1b[2m{}\x1b[0m", size as f64, suffix[0]); }
    let mut s = size as f64; let mut i = 0;
    while s >= base && i < suffix.len() - 1 { s /= base; i += 1; }
    format!("{:>5.1} \x1b[2m{}\x1b[0m", s, suffix[i])
}

fn get_permissions_str(mode: u32) -> String {
    let r = "\x1b[33mr\x1b[0m"; let w = "\x1b[31mw\x1b[0m"; let x = "\x1b[32mx\x1b[0m"; let d = "\x1b[2m-\x1b[0m";
    let mut s = String::new();
    for i in (0..3).rev() {
        let b = (mode >> (i * 3)) & 0x7;
        s.push_str(if b & 4 != 0 { r } else { d });
        s.push_str(if b & 2 != 0 { w } else { d });
        s.push_str(if b & 1 != 0 { x } else { d });
