        }
        i += 1;
    }
    if opts.paths.is_empty() { opts.paths.push(PathBuf::from(".")); }
    if opts.details.is_empty() { opts.details.push("none".to_string()); }

    for (idx, path) in opts.paths.iter().enumerate() {
        if opts.paths.len() > 1 { if idx > 0 { println!(); } println!("{}:", path.display()); }
        let mut nodes = Vec::new();
        if let Ok(entries) = fs::read_dir(path) {
            for entry in entries.flatten() {
                let name = entry.file_name().into_string().unwrap_or_default();
                if name.starts_with('.') && opts.importance >= 0 { continue; }
                let metadata = entry.metadata().unwrap();
