fn print_node_recursive(node: &NodeInfo, opts: &Options, indent: &str) {
    if opts.details[0] != "none" {
        for det in &opts.details {
            match det.as_str() {
                "nlink" => print!("{:>5} ", node.metadata.nlink()),
