    } else { ("", "") };
    let mut res = format!("{}", indent);
    if options.show_icons {
        if icon.is_empty() { res.push_str("   "); }
        else {
            if !icon_color.is_empty() { res.push_str(&format!("\x1b[{}m{}\x1b[0m ", icon_color, icon)); }
