    }
    if is_link { return ("\u{f339}", "35"); }
    if is_pipe { return ("\u{f07e5}", "33"); }
    if is_socket { return ("\u{f07e8}", "32"); }
    let ln = name.to_lowercase();
    if ln == "license" { return ("\u{f495}", ""); }
    if ln == "readme.md" { return ("\u{f02d}", ""); }
    if ln == "makefile" { return ("\u{f070e}", ""); }
    if ln == "cargo.toml" { return ("\u{f487}", ""); }
    if ln == "cargo.lock" { return ("\u{f456}", ""); }
    if ln == "dockerfile" { return ("\u{f4b7}", ""); }
    if ln == ".gitignore" { return ("\u{f2a2}", ""); }
    if let Some(ext) = Path::new(name).extension().and_then(|s| s.to_str()) {
        match ext.to_lowercase().as_str() {
            "rs" => return ("\u{e68b}", "91"),
            "md" => return ("\u{f48a}", ""),
            "json" | "yaml" | "toml" => return ("\u{e60b}", ""),
            "sh" => return ("\u{f489}", ""),
            "txt" => return ("\u{e612}", ""),
            "mkv" | "mp4" => return ("\u{f0567}", ""),
            "png" | "jpg" | "jpeg" | "gif" | "svg" => return ("\u{f02e9}", ""),
            "mp3" | "wav" => return ("\u{f04c3}", ""),
            _ => {}
        }
    }
    ("", "")
}

fn format_name(name: &str, info: &NodeInfo, options: &Options, dim: bool, indent: &str) -> String {
    let (icon, icon_color) = if options.show_icons {
        get_icon(name, info.metadata.is_dir(), info.is_symlink, info.metadata.file_type().is_fifo(), info.metadata.file_type().is_socket())
    } else { ("", "") };
    let mut res = format!("{}", indent);
    if options.show_icons {
        if icon.is_empty() { res.push_str("   "); }
        else {
            if !icon_color.is_empty() { res.push_str(&format!("\x1b[{}m{}\x1b[0m ", icon_color, icon)); }
            else { res.push_str(&format!("{} ", icon)); }
            if !(name.starts_with('.') && options.align_dotfiles) { res.push_str(" "); }
        }
    }
    if name.starts_with('.') && options.align_dotfiles {
        if !options.show_icons { res.push_str("  "); }
        res.push_str("\x1b[2m.\x1b[0m");
        let rest = &name[1..];
        let style = if info.metadata.is_dir() { "\x1b[2;34m" } else if dim { "\x1b[2m" } else { "" };
        if !style.is_empty() { res.push_str(&format!("{}{}\x1b[0m", style, rest)); } else { res.push_str(rest); }
    } else {
        if !options.show_icons { res.push_str("   "); }
        let style = if info.metadata.is_dir() { "\x1b[34m" }
                    else if name == "LICENSE" || name == "executable" { "\x1b[3m" }
                    else if name == "README.md" { "\x1b[4m" }
                    else if name.ends_with(".rs") { "\x1b[91m" }
                    else if dim { "\x1b[2m" } else { "" };
        if !style.is_empty() { res.push_str(&format!("{}{}\x1b[0m", style, name)); } else { res.push_str(name); }
    }
    if options.show_suffix {
        if info.metadata.is_dir() { res.push_str("\x1b[2;34m/\x1b[0m"); }
        else if info.is_symlink { res.push_str("\x1b[2m@\x1b[0m"); }
        else if info.metadata.file_type().is_fifo() { res.push_str("\x1b[2m|\x1b[0m"); }
        else if info.metadata.file_type().is_socket() { res.push_str("\x1b[2m=\x1b[0m"); }
    }
    if options.show_symlink_targets && info.is_symlink {
        if let Some(target) = &info.symlink_target { res.push_str(&format!(" \x1b[35m\u{f0054}\x1b[0m {}", target)); }
    }
    res
}

fn main() {
    let mut opts = Options {
        paths: Vec::new(), details: Vec::new(), importance: 0, sort: vec!["cat".to_string(), "cname".to_string()],
        show_icons: true, show_suffix: true, show_symlink_targets: true, align_dotfiles: true,
        units: "binary".to_string(), header: true, collapse: true,
    };
    let args: Vec<String> = env::args().collect();
    let mut i = 1;
    while i < args.len() {
        match args[i].as_str() {
            "-h" | "--help" => { println!("Usage: pls [OPTIONS] [PATHS]..."); return; }
            "-V" | "--version" => { println!("pls 0.0.1-beta.9"); return; }
            "-d" | "--det" => { i += 1; if i < args.len() { match args[i].as_str() {
                "std" => opts.details.extend(vec!["nlink", "typ", "perm", "user", "group", "size", "mtime"].into_iter().map(|s| s.to_string())),
                "all" => opts.details.extend(vec!["dev", "ino", "nlink", "typ", "perm", "oct", "user", "uid", "group", "gid", "size", "blocks", "btime", "ctime", "mtime", "atime", "git"].into_iter().map(|s| s.to_string())),
                det => opts.details.push(det.to_string()),
            } } }
            "-I" | "--imp" => { i += 1; if i < args.len() {
                if args[i] == "--" { i += 1; opts.importance = args[i].parse().unwrap_or(0); }
                else { opts.importance = args[i].parse().unwrap_or(0); }
            } }
            "-s" | "--sort" => { i += 1; if i < args.len() { opts.sort = args[i].split_whitespace().map(|s| s.to_string()).collect(); } }
            "-u" | "--unit" => { i += 1; if i < args.len() { opts.units = args[i].clone(); } }
            "-H" | "--header" => { i += 1; if i < args.len() { opts.header = args[i] == "true"; } }
            "-S" | "--suffix" => { i += 1; if i < args.len() { opts.show_suffix = args[i] == "true"; } }
            "-l" | "--sym" => { i += 1; if i < args.len() { opts.show_symlink_targets = args[i] == "true"; } }
            "-i" | "--icon" => { i += 1; if i < args.len() { opts.show_icons = args[i] == "true"; } }
            "-c" | "--collapse" => { i += 1; if i < args.len() { opts.collapse = args[i] == "true"; } }
            "-a" | "--align" => { i += 1; if i < args.len() { opts.align_dotfiles = args[i] == "true"; } }
            arg if arg.starts_with("--imp=") => opts.importance = arg["--imp=".len()..].parse().unwrap_or(0),
            p if !p.starts_with('-') => opts.paths.push(PathBuf::from(p)),
            _ => {}
        }
        i += 1;
    }
    if opts.paths.is_empty() { opts.paths.push(PathBuf::from(".")); }
    if opts.details.is_empty() { opts.details.push("none".to_string()); }

    for (idx, path) in opts.paths.iter().enumerate() {
        if opts.paths.len() > 1 { if idx > 0 { println!(); } println!("{}:", path.display()); }
        let mut nodes = Vec::new();
        if let Ok(entries) = fs::read_dir(path) {
            for entry in entries.flatten() {
                let name = entry.file_name().into_string().unwrap_or_default();
                if name.starts_with('.') && opts.importance >= 0 { continue; }
                let metadata = entry.metadata().unwrap();
                let is_symlink = entry.file_type().unwrap().is_symlink();
                nodes.push(NodeInfo {
                    name, metadata, is_symlink,
                    symlink_target: if is_symlink { fs::read_link(entry.path()).ok().map(|p| p.display().to_string()) } else { None },
                    children: Vec::new(),
                });
            }
        } else if let Ok(metadata) = fs::symlink_metadata(path) {
            let is_symlink = fs::read_link(path).is_ok();
            nodes.push(NodeInfo {
                name: path.file_name().and_then(|s| s.to_str()).unwrap_or("").to_string(),
                metadata, is_symlink,
                symlink_target: if is_symlink { fs::read_link(path).ok().map(|p| p.display().to_string()) } else { None },
                children: Vec::new(),
            });
        }

        nodes.sort_by(|a, b| {
            for s in &opts.sort {
                let mut key = s.as_str();
                let rev = key.ends_with('_');
                if rev { key = &key[..key.len()-1]; }
                let cmp = match key {
                    "cat" => (if a.metadata.is_dir() { 0 } else { 1 }).cmp(&(if b.metadata.is_dir() { 0 } else { 1 })),
                    "cname" => a.name.to_lowercase().cmp(&b.name.to_lowercase()),
                    "size" => a.metadata.len().cmp(&b.metadata.len()),
                    "ext" => {
                        let ea = Path::new(&a.name).extension().and_then(|s| s.to_str()).unwrap_or("");
                        let eb = Path::new(&b.name).extension().and_then(|s| s.to_str()).unwrap_or("");
                        ea.to_lowercase().cmp(&eb.to_lowercase())
                    }
                    _ => std::cmp::Ordering::Equal,
                };
                if cmp != std::cmp::Ordering::Equal { return if rev { cmp.reverse() } else { cmp }; }
            }
            std::cmp::Ordering::Equal
        });

        if opts.collapse {
            let mut j = 0;
            while j < nodes.len() {
                if nodes[j].name == "Cargo.lock" {
                    if let Some(pos) = nodes.iter().position(|n| n.name == "Cargo.toml") {
                        let lock = nodes.remove(j);
                        nodes[pos].children.push(lock);
                        continue;
                    }
                }
                j += 1;
            }
        }

        if opts.details[0] != "none" && opts.header && path.is_dir() {
            for det in &opts.details {
                let (h, w) = match det.as_str() { "nlink" => ("Link#", 5), "typ" => ("T", 1), "perm" => ("Permissions", 11), "user" => ("User", 5), "group" => ("Group", 10), "size" => ("Size", 10), "mtime" => ("Modified", 20), "oct" => ("SUGO", 4), _ => (det.as_str(), 0) };
                print!("\x1b[1;4;3m{:>width$}\x1b[0m ", h, width = w);
            }
            println!("\x1b[1;4;3mName\x1b[0m");
        }
        for node in nodes { print_node_recursive(&node, &opts, ""); }
    }
}

fn print_node_recursive(node: &NodeInfo, opts: &Options, indent: &str) {
    if opts.details[0] != "none" {
        for det in &opts.details {
            match det.as_str() {
                "nlink" => print!("{:>5} ", node.metadata.nlink()),
                "typ" => print!("{} ", if node.metadata.is_dir() { "\x1b[34md\x1b[0m" } else if node.is_symlink { "l" } else { "\x1b[2mf\x1b[0m" }),
                "perm" => print!("{} ", get_permissions_str(node.metadata.mode())),
                "user" => { let uid = node.metadata.uid(); if uid == 1000 { print!("\x1b[1;34magent\x1b[0m "); } else if uid == 0 { print!("\x1b[2mroot\x1b[0m  "); } else { print!("{:<5} ", uid); } }
                "group" => { let gid = node.metadata.gid(); if gid == 1000 { print!("\x1b[2magent\x1b[0m "); } else if gid == 0 { print!("\x1b[2mroot\x1b[0m  "); } else { print!("{:<10} ", "agent"); } }
                "size" => { if node.metadata.is_dir() { print!("           "); } else { print!("{} ", format_size(node.metadata.len(), &opts.units)); } }
                "mtime" => print!("{} ", format_time(node.metadata.mtime())),
                "oct" => print!("{:>4} ", format!("{:o}", node.metadata.mode() & 0o7777)),
                _ => {}
            }
        }
    }
    println!("{}", format_name(&node.name, node, opts, node.name.starts_with('.'), indent));
    for child in &node.children { print_node_recursive(child, opts, "   └─ "); }
}

fn format_size(size: u64, units: &str) -> String {
    let (base, suffix) = if units == "decimal" { (1000.0, vec!["B", "KB", "MB", "GB", "TB"]) } else { (1024.0, vec!["B", "KiB", "MiB", "GiB", "TiB"]) };
    if size < base as u64 { return format!("{:>5.1}   \x1b[2m{}\x1b[0m", size as f64, suffix[0]); }
    let mut s = size as f64; let mut i = 0;
    while s >= base && i < suffix.len() - 1 { s /= base; i += 1; }
    format!("{:>5.1} \x1b[2m{}\x1b[0m", s, suffix[i])
}

fn get_permissions_str(mode: u32) -> String {
    let r = "\x1b[33mr\x1b[0m"; let w = "\x1b[31mw\x1b[0m"; let x = "\x1b[32mx\x1b[0m"; let d = "\x1b[2m-\x1b[0m";
    let mut s = String::new();
    for i in (0..3).rev() {
        let b = (mode >> (i * 3)) & 0x7;
        s.push_str(if b & 4 != 0 { r } else { d });
        s.push_str(if b & 2 != 0 { w } else { d });
        s.push_str(if b & 1 != 0 { x } else { d });
        if i > 0 { s.push_str(" "); }
    }
    s
}
EOF
cat <<'EOF' > Cargo.toml
[package]
name = "pls"
version = "0.1.0"
edition = "2021"

[dependencies]
EOF
./compile.sh
"}
